T//made of Karo edit

freq = effect("Freq")("Slider");
decay = effect("Decay")("Slider");
duration = effect("Duration")("Slider");

retardFrames = effect("Retard")("Slider"); //
mode = effect("Mode")("Slider")/100;       // 0 = Ramp | 1 = Square

delay = framesToTime(retardFrames);

// Delay Ramp
rampDelay = (textIndex-1) * thisComp.frameDuration;

// Delay Square
squareDelay = (textIndex-1) * delay;

// Blend
Square
retard = linear(mode,0,1,rampDelay,squareDelay);

t = time - (inPoint + retard);

startVal = [100,100,100];
endVal = [0,0,0];

if (t < duration){
    linear(t,0,duration,startVal,endVal);
}else{
    amp = (endVal-startVal)/duration;
    w = freq*Math.PI*2;
    endVal + amp * (Math.sin((t-duration)*w) / Math.exp(decay*(t-duration)) / w);
}


